const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({
    viewport: { width: 1400, height: 2500 },
    deviceScaleFactor: 2,
  });
  const page = await context.newPage();

  const htmlPath = path.resolve(__dirname, 'poster.html');
  await page.goto('file://' + htmlPath, { waitUntil: 'networkidle' });

  // Wait for fonts to load
  await page.evaluate(() => document.fonts.ready);
  await page.waitForTimeout(1000);

  const poster = await page.$('.poster');
  const box = await poster.boundingBox();

  await poster.screenshot({
    path: '/app/output/final_poster.png',
    type: 'png',
    clip: {
      x: box.x,
      y: box.y,
      width: box.width,
      height: box.height,
    },
  });

  console.log('Poster saved to /app/output/final_poster.png');
  console.log('Dimensions:', box.width * 2, 'x', box.height * 2);

  await browser.close();
})();
